// Helper function to write data to a temporary file
static FILE*  id_000002_create_temp_file(const uint8_t *data, size_t size, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return nullptr;
    fwrite(data, 1, size, file);
    assert_file_closed(&file);;
    return fopen(filename, "rb");
}

// Custom I/O handlers for TIFFClientOpen
static tmsize_t  id_000002_tiff_read_proc(thandle_t handle, void *buf, tmsize_t size) {
    return (tmsize_t)fread(buf, 1, size, (FILE*)handle);
}

static tmsize_t  id_000002_tiff_write_proc(thandle_t handle, void *buf, tmsize_t size) {
    return (tmsize_t)fwrite(buf, 1, size, (FILE*)handle);
}

static toff_t  id_000002_tiff_seek_proc(thandle_t handle, toff_t offset, int whence) {
    if (fseek((FILE*)handle, (long)offset, whence) != 0)
        return (toff_t)-1;
    return ftell((FILE*)handle);
}

static int  id_000002_tiff_close_proc(thandle_t handle) {
    return fclose((FILE*)handle);
}

static toff_t  id_000002_tiff_size_proc(thandle_t handle) {
    long current = ftell((FILE*)handle);
    fseek((FILE*)handle, 0, SEEK_END);
    long size = ftell((FILE*)handle);
    fseek((FILE*)handle, current, SEEK_SET);
    return (toff_t)size;
}

